import * as React from "react";
import { render, screen } from "@testing-library/react";
import mediaQuery from "css-mediaquery";
import tokens from "@airbus/design-tokens";
import Hidden from ".";

function createMatchMedia(width: number) {
  // console.log('createMatchMedia', width);
  return (query: string): any => ({
    matches: mediaQuery.match(query, { width }),
    addListener: () => {},
    removeListener: () => {},
  });
}

const breakpoints = tokens.airbus.responsive.breakpoint;

describe("Hidden component", () => {
  describe("`on` property", () => {
    it("should not hide anything without a `on` prop", () => {
      render(
        <Hidden>
          <div data-testid="test" />
        </Hidden>
      );
      expect(screen.getByTestId("test")).toBeInTheDocument();
    });

    it("should hide at the breakpoint", () => {
      // @ts-ignore
      window.matchMedia = createMatchMedia(breakpoints.sm);
      render(
        <Hidden on="sm">
          <div data-testid="test" />
        </Hidden>
      );
      expect(screen.queryByTestId("test")).not.toBeInTheDocument();
    });

    it("should not hide outside the breakpoint", () => {
      // @ts-ignore
      window.matchMedia = createMatchMedia(breakpoints.xs);
      const { rerender } = render(
        <Hidden on="sm">
          <div data-testid="test1" />
        </Hidden>
      );
      expect(screen.getByTestId("test1")).toBeInTheDocument();

      window.matchMedia = createMatchMedia(breakpoints.xl);
      rerender(
        <Hidden on="sm">
          <div data-testid="test2" />
        </Hidden>
      );
      expect(screen.getByTestId("test2")).toBeInTheDocument();
    });

    it("should support an array of breakpoints", () => {
      // @ts-ignore
      window.matchMedia = createMatchMedia(breakpoints.md - 1);
      render(
        <Hidden on={["sm", "md"]}>
          <div data-testid="test" />
        </Hidden>
      );
      expect(screen.queryByTestId("test")).not.toBeInTheDocument();
    });
  });

  describe("`up` property", () => {
    it("should hide at the breakpoint", () => {
      // @ts-ignore
      window.matchMedia = createMatchMedia(breakpoints.sm);
      render(
        <Hidden up="sm">
          <div data-testid="test" />
        </Hidden>
      );
      expect(screen.queryByTestId("test")).not.toBeInTheDocument();
    });

    it("should hide above the breakpoint", () => {
      // @ts-ignore
      window.matchMedia = createMatchMedia(breakpoints.lg);
      render(
        <Hidden up="md">
          <div data-testid="test" />
        </Hidden>
      );
      expect(screen.queryByTestId("test")).not.toBeInTheDocument();
    });

    it("should not hide before the breakpoint", () => {
      // @ts-ignore
      window.matchMedia = createMatchMedia(breakpoints.sm);
      render(
        <Hidden up="md">
          <div data-testid="test" />
        </Hidden>
      );
      expect(screen.getByTestId("test")).toBeInTheDocument();
    });
  });

  describe("`down` property", () => {
    it("should hide at the breakpoint - 1", () => {
      // @ts-ignore
      window.matchMedia = createMatchMedia(breakpoints.md - 1);
      render(
        <Hidden down="md">
          <div data-testid="test" />
        </Hidden>
      );
      expect(screen.queryByTestId("test")).not.toBeInTheDocument();
    });

    it("should hide below the breakpoint", () => {
      // @ts-ignore
      window.matchMedia = createMatchMedia(breakpoints.sm);
      render(
        <Hidden down="md">
          <div data-testid="test" />
        </Hidden>
      );
      expect(screen.queryByTestId("test")).not.toBeInTheDocument();
    });

    it("should not hide after the breakpoint", () => {
      // @ts-ignore
      window.matchMedia = createMatchMedia(breakpoints.lg);
      render(
        <Hidden down="md">
          <div data-testid="test" />
        </Hidden>
      );
      expect(screen.getByTestId("test")).toBeInTheDocument();
    });
  });
});
